<section class="sales-start"><span class="eyebrow">Choose what to view</span><h2>Which sales do you want to see?</h2><p>Select one button to open its complete invoice list.</p><div class="sales-view-cards"><a class="cash" href="?view=cash"><span>Rs</span><strong>Cash Sales</strong><small>Sales paid fully at the time of sale</small><b>View Cash Sales →</b></a><a class="credit" href="?view=credit"><span>CR</span><strong>Credit Sales</strong><small>Paid, unpaid, partially paid and overdue credit invoices</small><b>View Credit Sales →</b></a><a class="all" href="?view=all"><span>ALL</span><strong>All Sales</strong><small>Cash and credit invoices together</small><b>View All Sales →</b></a></div></section><section class="sales-view-flow"><span>1 Choose sales</span><i>→</i><span>2 Search or filter</span><i>→</i><span>3 Open full invoice</span></section><style>.sales-start{background:#fff;border:1px solid #e3e8e2;border-radius:18px;padding:34px;box-shadow:0 12px 36px rgba(31,49,39,.07)}.sales-start h2{font-size:28px;margin:8px 0}.sales-start>p{color:#718078}.sales-view-cards{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:18px;margin-top:28px}.sales-view-cards>a{min-height:225px;border:2px solid #e3e8e2;border-radius:16px;padding:24px;display:flex;flex-direction:column;align-items:flex-start;transition:.15s}.sales-view-cards>a:hover{transform:translateY(-3px);box-shadow:0 14px 30px rgba(31,49,39,.1)}.sales-view-cards>a>span{width:52px;height:52px;border-radius:50%;display:grid;place-items:center;background:#edf4e9;color:#174e39;font-weight:800}.sales-view-cards strong{font-size:23px;margin:18px 0 7px}.sales-view-cards small{color:#718078;line-height:1.5;flex:1}.sales-view-cards b{margin-top:20px;color:#174e39}.sales-view-cards .cash{border-top:6px solid #2e9b58}.sales-view-cards .credit{border-top:6px solid #d18b2e}.sales-view-cards .all{border-top:6px solid #3973b7}.sales-view-flow{display:flex;align-items:center;justify-content:center;gap:14px;margin:22px;color:#718078;font-weight:700}.sales-view-flow i{width:30px;height:30px;border-radius:50%;background:#cbe85b;color:#174e39;display:grid;place-items:center;font-style:normal}@media(max-width:800px){.sales-view-cards{grid-template-columns:1fr}.sales-view-flow{flex-direction:column}.sales-view-flow i{transform:rotate(90deg)}}</style><?php page_end();exit;}$q=trim($_GET['q']??'');$from=$_GET['from']??date('Y-m-01');$to=$_GET['to']??date('Y-m-d');$payment=$view==='all'?'':$view;$saleType=$_GET['sale_type']??'';$status=$_GET['status']??'';$where=['DATE(s.sale_date) BETWEEN ? AND ?'];$params=[$from,$to];if($q!==''){$where[]='(s.sale_no LIKE ? OR c.name LIKE ? OR c.phone LIKE ? OR p.name LIKE ? OR p.item_code LIKE ?)';$like="%$q%";array_push($params,$like,$like,$like,$like,$like);}if(in_array($payment,['cash','credit'],true)){$where[]='s.payment_type=?';$params[]=$payment;}if(in_array($saleType,['retail','wholesale'],true)){$where[]='s.sale_type=?';$params[]=$saleType;}if($status!==''){$where[]='s.status=?';$params[]=$status;}$sql='SELECT DISTINCT s.*,COALESCE(c.name,"Walk-in Customer") customer,c.phone,u.display_name cashier FROM sales s LEFT JOIN customers c ON c.id=s.customer_id JOIN users u ON u.id=s.created_by LEFT JOIN sale_items si ON si.sale_id=s.id LEFT JOIN products p ON p.id=si.product_id WHERE '.implode(' AND ',$where).' ORDER BY s.sale_date DESC,s.id DESC';$stmt=$db->prepare($sql);$stmt->execute($params);$rows=$stmt->fetchAll();$totals=['count'=>count($rows),'sales'=>array_sum(array_column($rows,'total')),'paid'=>array_sum(array_column($rows,'paid_amount')),'balance'=>array_sum(array_column($rows,'balance'))];page_start($view==='cash'?'Cash Sales':($view==='credit'?'Credit Sales':'All Sales'),'sales_list.php');?>
