<style>.sales-view-switch{display:flex;align-items:center;gap:10px;background:#fff;border:1px solid #e3e8e2;border-radius:13px;padding:11px 14px;margin-bottom:18px}.sales-view-switch a{padding:9px 13px;border-radius:8px;font-weight:700}.sales-view-switch a:first-child{margin-right:auto;background:#edf4e9;color:#174e39}.sales-view-switch a.active{background:#174e39;color:#fff}.sales-view-switch a.active.credit{background:#a96d1e}.sales-view-switch a.active.all{background:#3973b7}.sales-view-switch i{width:25px;height:25px;border-radius:50%;background:#cbe85b;color:#174e39;display:grid;place-items:center;font-style:normal}@media(max-width:750px){.sales-view-switch{align-items:stretch;flex-direction:column}.sales-view-switch a:first-child{margin:0}.sales-view-switch i{margin:auto;transform:rotate(90deg)}}</style><script>document.addEventListener('DOMContentLoaded',()=>{const form=document.querySelector('.sales-filters');if(!form)return;const hidden=document.createElement('input');hidden.type='hidden';hidden.name='view';hidden.value=<?=json_encode($view)?>;form.appendChild(hidden);const payment=form.querySelector('select[name="payment"]');if(payment){payment.value=<?=json_encode($payment)?>;payment.disabled=true;const label=payment.closest('label');if(label)label.firstChild.textContent='Showing ('+(<?=json_encode($view)?>==='cash'?'Cash Sales':(<?=json_encode($view)?>==='credit'?'Credit Sales':'All Sales'))+')'}});</script>
<style>.due-payment{font-weight:800;color:#b23a34}.due-payment.cleared{color:#28784a}.sales-register-table th,.sales-register-table td{padding-left:12px;padding-right:12px}.sales-register-table td:nth-child(2){white-space:normal;min-width:210px}</style><script>document.addEventListener('DOMContentLoaded',()=>{const table=document.querySelector('.table-panel table');if(!table)return;table.classList.add('sales-register-table');const header=table.querySelector('thead tr');const totalHeader=header?.querySelector('th.right');if(totalHeader){const dueHeader=document.createElement('th');dueHeader.className='right';dueHeader.textContent='Due Payment';header.insertBefore(dueHeader,totalHeader)}const balances=<?=json_encode(array_map(fn($r)=>(float)$r['balance'],$rows))?>,bodies=table.querySelectorAll('tbody tr');bodies.forEach((tr,index)=>{if(index>=balances.length)return;const cells=tr.querySelectorAll('td');if(cells.length<2)return;const totalCell=cells[cells.length-2],due=document.createElement('td'),amount=Number(balances[index]||0);due.className='right due-payment'+(amount<=0?' cleared':'');due.textContent='Rs. '+amount.toLocaleString('en-LK',{minimumFractionDigits:2,maximumFractionDigits:2});tr.insertBefore(due,totalCell);const paymentNote=cells[3]?.querySelector('small');if(paymentNote&&paymentNote.textContent.trim().startsWith('Due '))paymentNote.remove()});const foot=table.querySelector('tfoot tr');if(foot){const totalCells=foot.querySelectorAll('th');const last=totalCells[totalCells.length-1];if(last&&last.colSpan===2)last.colSpan=3}});</script>
<section class="action-banner"><div><span class="step-number">1</span><div><b>Find any sale or invoice</b><p>Search invoice number, customer, phone, product name or item code.</p></div></div><a class="btn primary" href="sale.php">+ New Sale</a></section><section class="panel"><form class="sales-filters"><label class="wide">Search<input name="q" value="<?=e($q)?>" placeholder="Invoice, customer, phone or product"></label><label>From<input type="date" name="from" value="<?=e($from)?>"></label><label>To<input type="date" name="to" value="<?=e($to)?>"></label><label>Cash / Credit<select name="payment"><option value="">All</option><option value="cash" <?=$payment==='cash'?'selected':''?>>Cash sales</option><option value="credit" <?=$payment==='credit'?'selected':''?>>Credit sales</option></select></label><label>Retail / Wholesale<select name="sale_type"><option value="">All</option><option value="retail" <?=$saleType==='retail'?'selected':''?>>Retail</option><option value="wholesale" <?=$saleType==='wholesale'?'selected':''?>>Wholesale</option></select></label><label>Status<select name="status"><option value="">All</option><?php foreach(['paid','unpaid','partially_paid','overdue','cancelled','returned'] as $v):?><option value="<?=$v?>" <?=$status===$v?'selected':''?>><?=e(ucwords(str_replace('_',' ',$v)))?></option><?php endforeach;?></select></label><button class="btn primary">Show Sales</button></form></section><section class="kpi-grid sales-kpis"><article class="kpi"><span>Invoices</span><strong><?=$totals['count']?></strong></article><article class="kpi"><span>Total sales</span><strong><?=money($totals['sales'])?></strong></article><article class="kpi"><span>Received</span><strong><?=money($totals['paid'])?></strong></article><article class="kpi"><span>Still due</span><strong><?=money($totals['balance'])?></strong></article></section><section class="panel table-panel"><div class="panel-head"><div><span class="eyebrow">Full sales register</span><h3><?=count($rows)?> sales found</h3></div><div><a class="btn secondary" href="reports.php?type=sales&from=<?=e($from)?>&to=<?=e($to)?>">Sales Report</a> <button class="btn secondary" onclick="window.print()">Print</button></div></div><div class="table-wrap"><table><thead><tr><th>Invoice</th><th>Customer</th><th>Sale</th><th>Payment</th><th>Date</th><th>Cashier</th><th>Status</th><th class="right">Total</th><th></th></tr></thead><tbody><?php if(!$rows):?><tr><td colspan="9"><div class="empty-state compact"><b>No sales match these filters</b></div></td></tr><?php endif;?><?php foreach($rows as $r):?><tr><td><b><?=e($r['sale_no'])?></b></td><td><?=e($r['customer'])?><br><small class="muted"><?=e($r['phone']??'')?></small></td><td><span class="tag"><?=e($r['sale_type'])?></span></td><td><?=e(ucfirst($r['payment_type']))?><?php if($r['balance']>0):?><br><small class="muted">Due <?=money($r['balance'])?></small><?php endif;?></td><td><?=date('d M Y, H:i',strtotime($r['sale_date']))?></td><td><?=e($r['cashier'])?></td><td><span class="status <?=e($r['status'])?>"><?=e(str_replace('_',' ',$r['status']))?></span></td><td class="right"><b><?=money($r['total'])?></b></td><td><a class="btn secondary" href="sale_view.php?id=<?=$r['id']?>">View</a><?php if(can('reports.view')):?> <a class="row-edit" href="edit_record.php?type=sale&id=<?=$r['id']?>">Correct</a><?php endif;?></td></tr><?php endforeach;?></tbody></table></div></section><style>.sales-filters{display:grid;grid-template-columns:2fr repeat(5,1fr) auto;gap:10px;align-items:end}.sales-kpis{margin-top:18px}@media(max-width:1200px){.sales-filters{grid-template-columns:repeat(3,1fr)}.sales-filters .wide{grid-column:span 2}}@media(max-width:700px){.sales-filters{grid-template-columns:1fr}.sales-filters .wide{grid-column:auto}}</style><?php page_end();
